import json

base = "bench/results/2026-10-12/m1-ngram/replay"
def rows(label):
    return {r["id"]: r for r in (json.loads(l) for l in open(f"{base}/{label}-greedy/requests.jsonl") if l.strip()) if r["fg_bg"]=="fg"}
off = {r["id"]: (r["phase"], r) for r in (json.loads(l) for l in open(f"{base}/off-greedy/requests.jsonl") if l.strip())}

print("=== length-row ids: off vs A vs B per phase ===")
for ph in ["single-agent","dual-agent"]:
    for arm in ["off","A","B"]:
        pass
for label in ["off","A","B"]:
    d = {r["phase"]:(r for r in (json.loads(l) for l in open(f"{base}/{label}-greedy/requests.jsonl") if l.strip()))}
print("off per-phase finish reasons for the 4 ids of interest:")
ids = ["inventory-baseline-r1/2/6","inventory-baseline-r1/2/8","inventory-mem0-r0/0/2","inventory-mem0-r2/0/2"]
import itertools
for label in ["off","A","B"]:
    print(f"\n--- {label} ---")
    for r in (json.loads(l) for l in open(f"{base}/{label}-greedy/requests.jsonl") if l.strip()):
        if r["fg_bg"]=="fg" and r["id"] in ids:
            print(r["phase"], r["id"], r["predicted_n"], r["finish_reason"], r["predicted_ms"])

print("\n=== out_sha256 identity (fg, per phase) vs off ===")
for label in ["A","B"]:
    d = {}
    for r in (json.loads(l) for l in open(f"{base}/{label}-greedy/requests.jsonl") if l.strip()):
        d.setdefault(r["phase"], []).append(r)
    for ph in ["single-agent","single-mem","dual-agent","dual-mem"]:
        n=match=0
        for r in d[ph]:
            o = off.get(r["id"])
            n+=1
            if o and o[1]["out_sha256"]==r["out_sha256"]: match+=1
        print(f"{label} {ph}: {match}/{n} identical to off")
