for label in ["off","A","B"]:
    print(f"--- {label} (length rows and those ids) ---")
    for r in allrows[label]:
        if r["fg_bg"]=="fg" and (r["finish_reason"]=="length" or r["id"] in ids):
            o = off_by_id_phase.get((r["phase"], r["id"]))
            oinfo = f" off:{o['predicted_n']}/{o['finish_reason']}" if o else ""
            print(f"{r['phase']:>13} {r['id']}: {r['predicted_n']:>5} {r['finish_reason']:>8}{oinfo}")
print("\n=== out_sha256 identity (fg, per phase) vs off ===")
for label in ["A","B"]:
    for ph in ["single-agent","single-mem","dual-agent","dual-mem"]:
        rr=[r for r in allrows[label] if r["fg_bg"]=="fg" and r["phase"]==ph]
        n=m=0
        for r in rr:
            o=off_by_id_phase.get((ph,r["id"]))
            n+=1
            if o and o["out_sha256"]==r["out_sha256"]: m+=1
        print(f"{label} {ph}: {m}/{n} identical to off")
